package com.minidc.common.event;

import java.time.Instant;
import java.util.List;
import java.util.UUID;

/**
 * Report generated by edge agents after scanning the local hypervisor for zombie or orphan sandboxes.
 */
public record ReconciliationReport(
        UUID nodeId,
        List<String> runningVmNames,
        List<String> orphanVmNames,
        List<String> cleanedVmNames,
        Instant timestamp
) {
    public ReconciliationReport {
        if (timestamp == null) {
            timestamp = Instant.now();
        }
        if (runningVmNames == null) {
            runningVmNames = List.of();
        }
        if (orphanVmNames == null) {
            orphanVmNames = List.of();
        }
        if (cleanedVmNames == null) {
            cleanedVmNames = List.of();
        }
    }
}

